import * as T from './three.module.js';
import {createGirl} from './character.js';
import {birthdayPose,phase,mix} from './choreography.js';
export function createBirthdayScene(canvas){
 const renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
 const scene=new T.Scene();scene.background=new T.Color(0x30233e);scene.fog=new T.FogExp2(0x281d3b,.025);const camera=new T.PerspectiveCamera(40,1,.1,60);
 const mat=(color,roughness=.5,metalness=0)=>new T.MeshStandardMaterial({color,roughness,metalness});const pink=mat(0xe998ba),cream=mat(0xfff2e3),gold=mat(0xeac583,.35,.55),sponge=mat(0xd9b087);
 function mesh(geometry,material,parent,p=[0,0,0],s){const m=new T.Mesh(geometry,material);m.position.set(...p);if(s)m.scale.set(...s);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
 function group(parent,p=[0,0,0]){const g=new T.Group();g.position.set(...p);parent.add(g);return g;}
 const ball=(parent,r,material,p,s)=>mesh(new T.SphereGeometry(r,20,12),material,parent,p,s);
 function rod(parent,a,b,r,material){const p=new T.Vector3(...a),q=new T.Vector3(...b),m=mesh(new T.CylinderGeometry(r,r,p.distanceTo(q),10),material,parent);m.position.copy(p).add(q).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),q.sub(p).normalize());return m;}
 scene.add(new T.HemisphereLight(0xe9dcff,0x51405b,1.7));const key=new T.DirectionalLight(0xffeadb,2.8);key.position.set(3,6,5);key.castShadow=true;key.shadow.mapSize.set(1536,1536);Object.assign(key.shadow.camera,{left:-5,right:5,top:5,bottom:-5});key.shadow.bias=-.0006;key.shadow.normalBias=.035;scene.add(key);const rim=new T.DirectionalLight(0xc6a7ff,1.6);rim.position.set(-3,3,-3);scene.add(rim);const fill=new T.DirectionalLight(0xfebedb,.9);fill.position.set(-4,2,4);scene.add(fill);
 mesh(new T.PlaneGeometry(100,100),mat(0x271c39),scene,[0,-.18,0]).rotation.x=-Math.PI/2;mesh(new T.CylinderGeometry(4,4.1,.16,80),mat(0x96768e),scene,[0,-.08,0]);const trim=mesh(new T.TorusGeometry(4.02,.022,6,80),gold,scene,[0,-.07,0]);trim.rotation.x=Math.PI/2;
 mesh(new T.TorusGeometry(2.3,.027,6,64,Math.PI),gold,scene,[0,0,-1.5]);for(let i=0;i<19;i++){const a=i/18*Math.PI;ball(scene,.040,new T.MeshBasicMaterial({color:0xffe0a5}),[Math.cos(a)*2.3,Math.sin(a)*2.3,-1.46]);}
 const balloons=[];for(const[x,y,z,c]of[[-2.8,2.4,-1.2,0xe7a3c5],[-2.5,1.9,-1,0xba9bd1],[2.5,2.3,-1,0xf2cc95],[2.9,2.8,-1.3,0xeaa8c9],[2.25,2.8,-1.7,0xb49dd8]]){const g=group(scene,[x,y,z]);ball(g,.27,mat(c,.25),[0,0,0],[1,1.28,1]);mesh(new T.ConeGeometry(.03,.06,6),mat(c),g,[0,-.345,0]).rotation.z=Math.PI;rod(g,[0,-.37,0],[.02,-y,0],.003,cream);balloons.push({g,y});}
 const stars=new T.BufferGeometry(),positions=[];for(let i=0;i<100;i++)positions.push((Math.random()-.5)*13,Math.random()*6+.5,-Math.random()*6-1);stars.setAttribute('position',new T.Float32BufferAttribute(positions,3));scene.add(new T.Points(stars,new T.PointsMaterial({color:0xffdfb0,size:.024,transparent:true,opacity:.75})));

 // A moonlit birthday garden: sculpted clouds, moon, presents and flowers.
 const moonMaterial=new T.MeshBasicMaterial({color:0xffe7b7});
 const crescent=new T.Shape();crescent.absarc(0,0,.55,.55,Math.PI*2-.55,false);crescent.quadraticCurveTo(-.70,0,.55*Math.cos(.55),.55*Math.sin(.55));
 const moon=mesh(new T.ShapeGeometry(crescent,40),moonMaterial,scene,[1.05,2.8,-2.7]);moon.rotation.z=-.28;moon.scale.setScalar(.72);moon.castShadow=false;
 const cloudMat=mat(0xc4afce,.95);
 for(const[x,y,z,size]of[[-1.8,3.15,-3,.8],[2.5,3.55,-3.7,.65]]){const g=group(scene,[x,y,z]);for(let i=0;i<5;i++)ball(g,.20*size,cloudMat,[(i-2)*.23*size,Math.sin(i/4*Math.PI)*.13*size,0],[1.4,1,.65]).castShadow=false;}
 const rug=mesh(new T.CylinderGeometry(1.8,1.8,.012,64),mat(0xc397ab),scene,[.1,.009,.2],[1.12,1,.8]);
 const rugTrim=mesh(new T.TorusGeometry(1.73,.012,6,64),gold,scene,[.1,.02,.2]);rugTrim.rotation.x=Math.PI/2;rugTrim.scale.set(1.12,.8,1);
 function gift(x,z,size,color){const g=group(scene,[x,size/2,z]),paper=mat(color,.65);mesh(new T.BoxGeometry(size,size,size),paper,g);mesh(new T.BoxGeometry(size*1.04,.055,size*1.04),paper,g,[0,size/2,0]);mesh(new T.BoxGeometry(size*.14,size+.065,size*1.045),gold,g);mesh(new T.BoxGeometry(size*1.045,size+.067,size*.14),gold,g);for(const side of[-1,1]){const bow=mesh(new T.TorusGeometry(size*.12,size*.025,6,16),gold,g,[side*size*.1,size*.59,0]);bow.rotation.y=side*.45;bow.scale.y=.65;}g.rotation.y=x*.25;}
 gift(1.7,-.48,.40,0xd8a3bc);gift(2.12,-.65,.30,0xbcaad8);gift(1.9,-.03,.24,0xf1d5ad);
 const petals=new T.InstancedMesh(new T.SphereGeometry(1,10,8),mat(0xf0b4ca,.8),180);const petalPose=new T.Object3D();let petalIndex=0;
 for(let i=0;i<30;i++){const a=i/29*Math.PI;const x=Math.cos(a)*2.05,z=-1.1-Math.sin(a)*.55,y=.12+(i%4)*.045;rod(scene,[x,.02,z],[x,y,z],.012,mat(0x77907c));ball(scene,.034,gold,[x,y,z]);for(let k=0;k<6;k++){const b=k/6*Math.PI*2;petalPose.position.set(x+Math.cos(b)*.045,y+.009,z+Math.sin(b)*.045);petalPose.scale.set(.048,.022,.027);petalPose.rotation.y=-b;petalPose.updateMatrix();petals.setMatrixAt(petalIndex++,petalPose.matrix);}}
 petals.receiveShadow=true;scene.add(petals);

 const table=group(scene,[.55,0,.05]);mesh(new T.CylinderGeometry(.90,.90,.08,64),mat(0xf2d6e0),table,[0,1.04,0],[.85,1,1.2]);mesh(new T.CylinderGeometry(.10,.14,1.02,20),gold,table,[0,.51,0]);mesh(new T.CylinderGeometry(.42,.48,.065,40),gold,table,[0,.02,0]);
 const plate=group(table,[-.10,1.10,.81]);mesh(new T.CylinderGeometry(.31,.29,.018,40),cream,plate);const plateRim=mesh(new T.TorusGeometry(.29,.014,6,40),gold,plate,[0,.012,0]);plateRim.rotation.x=Math.PI/2;
 const cake=group(table,[0,1.10,0]);mesh(new T.CylinderGeometry(.53,.53,.025,64),gold,cake,[0,.005,0]);const rest=group(cake),slice=group(cake);
 const start=Math.PI,end=1.5*Math.PI;
 function sector(parent,r,h,y,a,b,material){const s=new T.Shape();s.moveTo(0,0);s.lineTo(r*Math.cos(a),r*Math.sin(a));s.absarc(0,0,r,a,b,false);s.lineTo(0,0);const g=new T.ExtrudeGeometry(s,{depth:h,bevelEnabled:true,bevelSize:.004,bevelThickness:.004,bevelSegments:2,curveSegments:40});g.rotateX(-Math.PI/2);mesh(g,material,parent,[0,y,0]);}
 for(const[r,h,y,m]of[[.44,.06,.024,cream],[.435,.145,.084,sponge],[.444,.035,.229,pink],[.435,.145,.264,sponge],[.448,.065,.409,cream],[.455,.044,.474,pink]]){sector(slice,r,h,y,start,end,m);sector(rest,r,h,y,end,start+Math.PI*2,m);}
 for(let i=0;i<40;i++){const a=i/40*Math.PI*2,parent=a>=start&&a<=end?slice:rest;ball(parent,.025,cream,[.43*Math.cos(a),.528,-.43*Math.sin(a)]);}
 for(let i=0;i<20;i++){const a=i/20*Math.PI*2,parent=a>=start&&a<=end?slice:rest;const drip=ball(parent,.025,pink,[.447*Math.cos(a),.463,-.447*Math.sin(a)]);drip.scale.y=1.7+Math.sin(i*2)**2;}
 for(let i=0;i<24;i++){const a=i*2.4,r=.12+Math.sqrt(i/24)*.23,parent=(a%(Math.PI*2))>=start&&(a%(Math.PI*2))<=end?slice:rest;const sprinkle=mesh(new T.BoxGeometry(.024,.010,.008),i%3?cream:gold,parent,[r*Math.cos(a),.524,-r*Math.sin(a)]);sprinkle.rotation.y=a;}
 const flames=[],lights=[],smoke=[];for(let i=0;i<3;i++){const x=(i-1)*.16,z=-.04;mesh(new T.CylinderGeometry(.016,.016,.20,10),i%2?gold:mat(0xb596d2),rest,[x,.627,z]);rod(rest,[x,.72,z],[x,.751,z],.003,mat(0x402235));const f=ball(rest,.021,new T.MeshBasicMaterial({color:0xffd58a}),[x,.773,z],[.7,1.8,.7]);flames.push(f);const light=new T.PointLight(0xffb578,.22,.7);light.position.set(x,.76,z);rest.add(light);lights.push(light);for(let j=0;j<4;j++){const s=ball(cake,.018,new T.MeshBasicMaterial({color:0xd9d1df,transparent:true,opacity:.25}),[x,.78,z]);s.castShadow=false;s.visible=false;smoke.push({s,x,z,j,candle:i});}}
 // Cut marks remain on the cake only after the blade reaches the board.
 const cuts=[];for(const angle of[Math.PI,1.5*Math.PI]){const g=group(cake);const line=mesh(new T.BoxGeometry(.44,.49,.004),mat(0x925a71),g,[-.22, .265,0]);mesh(new T.BoxGeometry(.445,.004,.008),mat(0x9d657c),g,[-.223,.527,0]);g.rotation.y=angle-Math.PI;g.visible=false;cuts.push(g);}
 const girl=createGirl(T,scene);
 const knife=group(scene);const bladeShape=new T.Shape();bladeShape.moveTo(0,-.070);bladeShape.lineTo(.43,-.070);bladeShape.quadraticCurveTo(.54,-.057,.54,.062);bladeShape.lineTo(0,.070);bladeShape.closePath();const bladeGeo=new T.ExtrudeGeometry(bladeShape,{depth:.009,bevelEnabled:true,bevelSize:.003,bevelThickness:.002,bevelSegments:1,steps:1});bladeGeo.rotateY(-Math.PI/2);mesh(bladeGeo,mat(0xdce5e8,.18,.75),knife,[.004,0,.092]);const handle=mesh(new T.CapsuleGeometry(.027,.13,4,10),mat(0x593346),knife,[0,0,0]);handle.rotation.x=Math.PI/2;for(const z of[-.044,.044])ball(knife,.008,gold,[-.028,0,z]);const guard=mesh(new T.BoxGeometry(.055,.11,.018),gold,knife,[0,0,.085]);
 const breaths=[];for(let i=0;i<8;i++){const b=ball(scene,.010,new T.MeshBasicMaterial({color:0xf9f3ee,transparent:true,opacity:.18}),[0,0,0]);b.castShadow=false;b.visible=false;breaths.push(b);}
 const confetti=new T.InstancedMesh(new T.PlaneGeometry(.04,.065),new T.MeshStandardMaterial({side:T.DoubleSide,roughness:.8}),110);confetti.instanceMatrix.setUsage(T.DynamicDrawUsage);const seeds=[],dummy=new T.Object3D();for(let i=0;i<110;i++){seeds.push({x:(Math.random()-.5)*5.5,y:3+Math.random()*2.6,z:(Math.random()-.5)*3,speed:.5+Math.random()*.6,spin:Math.random()*4});confetti.setColorAt(i,new T.Color([0xffc3df,0xffd995,0xc2abed,0xfff5ed][i%4]));}scene.add(confetti);confetti.visible=false;
 const v=new T.Vector3(),look=new T.Vector3(),q=new T.Quaternion(),axisZ=new T.Vector3(0,0,1);let diagnostics={},orbit=null,lastTime=0;const orbitTarget=new T.Vector3(.1,1.35,.1);
 function render(t){lastTime=t;const p=birthdayPose(t);girl.pose(p);const d=new T.Vector3(...p.direction).normalize();q.setFromUnitVectors(axisZ,d);q.multiply(new T.Quaternion().setFromAxisAngle(axisZ,p.roll));const restHand=girl.restingHand(p,0);const target=restHand.clone().lerp(new T.Vector3(...p.knife),p.handReach);const held=girl.solveArm(0,target,p.grip,p.grip>.3?q:null);knife.quaternion.copy(q);knife.position.copy(p.grip>.001?held.position:new T.Vector3(...p.knife));
 const freeHand=girl.restingHand(p,1);const steady=phase(t,14.3,15.5)*(1-phase(t,24.2,25.4));freeHand.lerp(new T.Vector3(.05,1.12,.38),steady);if(p.farewell){const s=girl.shoulder(1);freeHand.lerp(s.add(new T.Vector3(.36+Math.sin(t*7)*.065,.44,.05).applyAxisAngle(new T.Vector3(0,1,0),p.yaw)),p.farewell);}const other=girl.solveArm(1,freeHand);if(p.farewell>.5){girl.arms[1].hand.rotation.set(0,.57,Math.PI+Math.sin(t*7)*.22);}
 slice.position.set(...p.slice);cuts[0].visible=p.cut1;cuts[1].visible=p.cut2;
 flames.forEach((f,i)=>{f.visible=p.flames[i];f.scale.y=1.8+Math.sin(t*14+i)*.15;lights[i].visible=f.visible;});smoke.forEach(({s,x,z,j,candle})=>{const a=t-(9.25+candle*.25)-j*.10;s.visible=a>0&&a<1.5;s.position.set(x+Math.sin(a*3+j)*.025,.78+a*.13,z);s.material.opacity=Math.max(0,.24*(1-a/1.5));s.scale.setScalar(1+Math.max(0,a)*1.5);});
 const mouth=girl.mouth(),candles=cake.localToWorld(new T.Vector3(0,.77,-.04));breaths.forEach((b,i)=>{b.visible=p.blowing;const f=((t-8.8)*2+i/8)%1;b.position.copy(mouth).lerp(candles,f);b.position.y+=Math.sin(i*2)*.01;b.material.opacity=.17*Math.sin(f*Math.PI);});
 balloons.forEach(({g,y},i)=>g.position.y=y+Math.sin(t+i)*.035);key.intensity=2.8-.45*(p.lean/.43)+.15*p.farewell;
 confetti.visible=t>=25.6;if(confetti.visible){const age=t-25.6;seeds.forEach((s,i)=>{dummy.position.set(s.x+Math.sin(age+s.spin)*.14,s.y-age*s.speed,s.z);dummy.rotation.set(age*s.spin,age*.7,s.spin);dummy.updateMatrix();confetti.setMatrixAt(i,dummy.matrix);});confetti.instanceMatrix.needsUpdate=true;}
 // Keep the face visible when blowing; make both blade cuts easy to see.
 const close=phase(t,5.2,7)*(1-phase(t,11,12));const cutting=phase(t,14.3,15.7)*(1-phase(t,24,25.6));v.set(mix(3.9,2.0,close),mix(3.25,2.9,close),mix(7.4,4.1,close));look.set(mix(-.15,.10,close),mix(1.22,1.80,close),.13);
 v.lerp(new T.Vector3(3.65,3.15,2.45),cutting);look.lerp(new T.Vector3(.10,1.40,.30),cutting);const goodbye=phase(t,26.3,28);v.lerp(new T.Vector3(2.3,2.75,5.0),goodbye);look.lerp(new T.Vector3(.05,1.47,.30),goodbye);if(camera.aspect<.8){v.sub(look).multiplyScalar(1.70).add(look);look.y+=.13;look.x-=.10;}if(orbit){v.setFromSpherical(orbit).add(orbitTarget);look.copy(orbitTarget);}camera.position.copy(v);camera.lookAt(look);renderer.render(scene,camera);
 diagnostics={cameraPosition:camera.position.toArray(),interactiveCamera:!!orbit,time:t,faceTurn:p.farewell,wishing:p.wish,flames:flames.map(f=>f.visible),cut1:p.cut1,cut2:p.cut2,slice:p.slice,knifeHeld:p.grip>.5,knifeGripError:p.grip>.5?held.position.distanceTo(knife.position):0,armReachError:held.reachError,otherArmReachError:other.reachError,knife:[...knife.position.toArray()],knifeTip:knife.localToWorld(new T.Vector3(0,0,.63)).toArray(),drawCalls:renderer.info.render.calls,titleOpacity:p.titleOpacity};return diagnostics;
 }
 function resize(t=0){const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();render(t);}
 function moveCamera(dx=0,dy=0,zoom=1){if(!orbit)orbit=new T.Spherical().setFromVector3(camera.position.clone().sub(orbitTarget));orbit.theta-=dx*.008;orbit.phi=T.MathUtils.clamp(orbit.phi+dy*.006,.32,1.68);orbit.radius=T.MathUtils.clamp(orbit.radius*zoom,2.4,12);render(lastTime);}
 function resetCamera(){orbit=null;render(lastTime);}
 function pick(clientX,clientY){const r=canvas.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((clientX-r.left)/r.width*2-1,-(clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObject(cake,true)[0];return hit?(hit.point.y>1.69?'candles':'cake'):null;}
 return {render,resize,moveCamera,resetCamera,pick,inspect:()=>diagnostics};
}
